		if (w.mg[MG.Prickle + id] > 0) w.mg[MG.Prickle + id]--;
		if (w.mg[MG.Feather + id] > 0) w.mg[MG.Feather + id]--;
		if (w.mg[MG.Hoard + id] > 0) w.mg[MG.Hoard + id]--;
